package com.robustvision.platform.service;
import com.robustvision.platform.common.BusinessException;
import com.robustvision.platform.domain.*;
import com.robustvision.platform.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;

@Service
public class GroupLifecycleService {
 private final JdbcTemplate db; private final WorkspaceRepository groups; private final WorkspaceMemberRepository members;
 private final UserRepository users; private final CurrentUserService current; private final WorkspaceService permissions;
 private final PasswordEncoder passwords; private final MessageRepository messages; private final MessageAttachmentRepository attachments;
 private final LiveUpdateService live;
 public GroupLifecycleService(JdbcTemplate db,WorkspaceRepository groups,WorkspaceMemberRepository members,UserRepository users,CurrentUserService current,WorkspaceService permissions,PasswordEncoder passwords,MessageRepository messages,MessageAttachmentRepository attachments,LiveUpdateService live){this.db=db;this.groups=groups;this.members=members;this.users=users;this.current=current;this.permissions=permissions;this.passwords=passwords;this.messages=messages;this.attachments=attachments;this.live=live;}
 private static BusinessException bad(String message){return new BusinessException(HttpStatus.BAD_REQUEST,"GROUP_OPERATION_INVALID",message);}
 private WorkspaceEntity lock(long id){return groups.findLockedById(id).orElseThrow(()->bad("群组不存在"));}
 private void owner(WorkspaceEntity g,UserEntity u){if(!current.isSuperAdmin(u)&&!g.getOwner().getId().equals(u.getId()))throw new BusinessException(HttpStatus.FORBIDDEN,"GROUP_OWNER_REQUIRED","只有群主或平台管理员可以操作");}
 private void manager(WorkspaceEntity g,UserEntity u){permissions.requireContentPermission(g.getId(),false); if(!current.isSuperAdmin(u)&&!g.getOwner().getId().equals(u.getId())){var m=members.findByWorkspaceIdAndUserId(g.getId(),u.getId()).orElseThrow();if(m.getRole()!=WorkspaceMemberRole.ADMIN||!m.getPermissions().contains("SETTINGS_WRITE"))throw new BusinessException(HttpStatus.FORBIDDEN,"GROUP_MANAGER_REQUIRED","需要群组管理权限");}}
 private void writable(WorkspaceEntity g){if(g.isArchived()||g.isDissolved())throw bad("群组已经归档，当前只能阅读");}
 private void notifyGroup(long id){live.changed(db.queryForList("SELECT user_id FROM workspace_member WHERE workspace_id=?",Long.class,id));}
 @Transactional(readOnly=true) public Map<String,Object> state(long id){permissions.requireContentPermission(id,false);var g=groups.findById(id).orElseThrow();return Map.of("archived",g.isArchived(),"dissolved",g.isDissolved(),"acceptRequests",g.isAcceptRequests());}
 @Transactional public void state(long id,boolean archived,boolean requests){var u=current.requireCurrent();var g=lock(id);owner(g,u);if(g.isDissolved())throw bad("已解散的群组不能恢复");g.lifecycle(archived,!archived&&requests);groups.saveAndFlush(g);notifyGroup(id);}
 @Transactional public void transfer(long id,long target,String password){var u=current.requireCurrent();var g=lock(id);owner(g,u);writable(g);proof(u,password);var targetUser=users.findById(target).filter(x->x.hasActiveAccess(Instant.now())).orElseThrow(()->bad("目标账号不可用"));if(target==g.getOwner().getId())throw bad("已经是当前群主");var next=members.findByWorkspaceIdAndUserId(id,target).orElseThrow(()->bad("新群主必须是群成员"));var old=members.findByWorkspaceIdAndUserId(id,g.getOwner().getId()).orElseThrow();old.update(WorkspaceMemberRole.ADMIN,WorkspaceService.ALL);next.update(WorkspaceMemberRole.OWNER,WorkspaceService.ALL);members.save(old);members.save(next);g.transfer(targetUser);groups.saveAndFlush(g);notifyGroup(id);}
 private void proof(UserEntity u,String password){if(password==null||!passwords.matches(password,u.getPasswordHash()))throw bad("当前密码不正确");}
 @Transactional public void dissolve(long id,String name,String password){var u=current.requireCurrent();var g=lock(id);owner(g,u);proof(u,password);if(!g.getName().equals(name))throw bad("请完整输入群组名称");var targets=db.queryForList("SELECT user_id FROM workspace_member WHERE workspace_id=?",Long.class,id);for(var m:members.findByWorkspaceIdOrderByCreatedAtAsc(id))if(!m.getUser().getId().equals(g.getOwner().getId()))members.delete(m);g.dissolve();groups.saveAndFlush(g);db.update("UPDATE group_invitation SET status='REJECTED' WHERE workspace_id=? AND status='PENDING'",id);live.changed(targets);}
 @Transactional public void invite(long id,long target,String role){var u=current.requireCurrent();var g=lock(id);manager(g,u);if(!permissions.detail(id).currentPermissions().contains("MEMBERS_WRITE"))throw new BusinessException(HttpStatus.FORBIDDEN,"GROUP_MEMBERS_REQUIRED","需要成员管理权限");writable(g);if(!Set.of("MEMBER","VIEWER").contains(role))throw bad("只能邀请普通成员或访客");var t=users.findById(target).filter(x->x.hasActiveAccess(Instant.now())).orElseThrow(()->bad("账号不可用"));if(blocked(u.getId(),target))throw bad("当前账号之间不能发送邀请");if(members.findByWorkspaceIdAndUserId(id,target).isPresent())throw bad("已经是群组成员");writeInvite(g,t.getId(),u.getId(),"INVITE",role);live.changed(List.of(target));}
 @Transactional public void request(long id){var u=current.requireCurrent();var g=lock(id);writable(g);if(!g.isAcceptRequests())throw bad("该群组未开放加入申请");if(members.findByWorkspaceIdAndUserId(id,u.getId()).isPresent())throw bad("已经是群组成员");writeInvite(g,u.getId(),u.getId(),"REQUEST","MEMBER");notifyGroup(id);}
 private boolean blocked(long a,long b){return db.queryForObject("SELECT COUNT(*) FROM contact_link WHERE ((low_user_id=? AND high_user_id=?) OR (low_user_id=? AND high_user_id=?)) AND (low_blocked=TRUE OR high_blocked=TRUE)",Integer.class,a,b,b,a)>0;}
 private void writeInvite(WorkspaceEntity g,long target,long actor,String kind,String role){if(db.queryForObject("SELECT COUNT(*) FROM group_invitation WHERE target_id=? AND status='PENDING' AND expires_at>?",Integer.class,target,Timestamp.from(Instant.now()))>=100)throw bad("待处理申请过多");var old=db.queryForList("SELECT id,status,expires_at FROM group_invitation WHERE workspace_id=? AND target_id=?",g.getId(),target);if(!old.isEmpty()&&old.get(0).get("status").equals("PENDING")&&JdbcTime.instant(old.get(0).get("expires_at")).isAfter(Instant.now()))throw bad("已有待处理的邀请或申请");if(!old.isEmpty())db.update("DELETE FROM group_invitation WHERE id=?",old.get(0).get("id"));db.update("INSERT INTO group_invitation(id,workspace_id,target_id,actor_id,kind,status,role,expires_at,created_at) VALUES (?,?,?,?,?,'PENDING',?,?,?)",UUID.randomUUID().toString(),g.getId(),target,actor,kind,role,Timestamp.from(Instant.now().plusSeconds(604800)),Timestamp.from(Instant.now()));}
 @Transactional(readOnly=true) public List<Map<String,Object>> invitations(Long group){var u=current.requireCurrent();if(group!=null)manager(groups.findById(group).orElseThrow(),u);return db.queryForList("SELECT i.id,i.workspace_id AS groupId,w.name AS groupName,i.target_id AS targetId,u.display_name AS displayName,u.identity_code AS identityCode,i.kind,i.role,i.expires_at AS expiresAt FROM group_invitation i JOIN workspace w ON w.id=i.workspace_id JOIN app_user u ON u.id=i.target_id WHERE i.status='PENDING' AND i.expires_at>? AND "+(group==null?"i.target_id=? AND i.kind='INVITE'":"i.workspace_id=?")+" ORDER BY i.created_at DESC LIMIT 100",Timestamp.from(Instant.now()),group==null?u.getId():group);}
 @Transactional public void decide(String id,boolean accept){var u=current.requireCurrent();var rows=db.queryForList("SELECT * FROM group_invitation WHERE id=?",id);if(rows.isEmpty())throw bad("申请不存在");var r=rows.get(0);var g=lock(((Number)r.get("workspace_id")).longValue());r=db.queryForMap("SELECT * FROM group_invitation WHERE id=? FOR UPDATE",id);long target=((Number)r.get("target_id")).longValue();if(r.get("kind").equals("INVITE")){if(target!=u.getId())throw new BusinessException(HttpStatus.FORBIDDEN,"INVITE_OWNER_REQUIRED","无权处理其他人的邀请");if(accept){var actor=users.findById(((Number)r.get("actor_id")).longValue()).filter(x->x.hasActiveAccess(Instant.now())).orElseThrow(()->bad("邀请人账号不可用"));if(!current.isSuperAdmin(actor)&&!g.getOwner().getId().equals(actor.getId())){var m=members.findByWorkspaceIdAndUserId(g.getId(),actor.getId()).orElseThrow(()->bad("邀请人已离开群组"));if(m.getRole()!=WorkspaceMemberRole.ADMIN||!m.getPermissions().contains("SETTINGS_WRITE")||!m.getPermissions().contains("MEMBERS_WRITE"))throw bad("邀请人已失去管理权限");}}}else {manager(g,u);if(!permissions.detail(g.getId()).currentPermissions().contains("MEMBERS_WRITE"))throw new BusinessException(HttpStatus.FORBIDDEN,"GROUP_MEMBERS_REQUIRED","需要成员管理权限");}
  if(!r.get("status").equals("PENDING")||!JdbcTime.instant(r.get("expires_at")).isAfter(Instant.now()))throw bad("邀请已经处理或过期");if(accept){writable(g);var t=users.findById(target).filter(x->x.hasActiveAccess(Instant.now())).orElseThrow(()->bad("成员账号不可用"));if(members.findByWorkspaceIdAndUserId(g.getId(),target).isEmpty()){var role=WorkspaceMemberRole.valueOf((String)r.get("role"));members.save(new WorkspaceMemberEntity(g,t,role,role==WorkspaceMemberRole.VIEWER?Set.of("CONTENT_READ"):Set.of("CONTENT_READ","CONTENT_WRITE","MEMBERS_READ")));}}db.update("UPDATE group_invitation SET status=? WHERE id=?",accept?"ACCEPTED":"REJECTED",id);notifyGroup(g.getId());live.changed(List.of(target));}
 @Transactional public void recall(long id,String messageId){var u=current.requireCurrent();var g=lock(id);permissions.requireContentPermission(id,false);var m=messages.findById(messageId).filter(x->Objects.equals(x.getWorkspaceId(),id)).orElseThrow(()->bad("消息不存在"));if(m.getRecalledAt()!=null)throw bad("消息已经撤回");if(!m.getSender().getId().equals(u.getId())||m.getCreatedAt().isBefore(Instant.now().minusSeconds(600)))manager(g,u);m.recall();messages.saveAndFlush(m);attachments.deleteAll(attachments.findByMessageIdOrderByIdAsc(messageId));notifyGroup(id);}
 @Transactional public void report(long id,String messageId,String reason){var u=current.requireCurrent();lock(id);permissions.requireContentPermission(id,false);messages.findById(messageId).filter(x->Objects.equals(x.getWorkspaceId(),id)).orElseThrow(()->bad("消息不存在"));if(db.queryForObject("SELECT COUNT(*) FROM group_report WHERE message_id=? AND reporter_id=?",Integer.class,messageId,u.getId())>0)throw bad("已经提交过举报");db.update("INSERT INTO group_report(id,workspace_id,message_id,reporter_id,reason,status,created_at) VALUES (?,?,?,?,?,'OPEN',?)",UUID.randomUUID().toString(),id,messageId,u.getId(),reason.trim(),Timestamp.from(Instant.now()));notifyGroup(id);}
 @Transactional(readOnly=true) public List<Map<String,Object>> reports(long id){manager(groups.findById(id).orElseThrow(),current.requireCurrent());return db.queryForList("SELECT r.id,r.message_id AS messageId,r.reason,r.status,r.created_at AS createdAt,u.display_name AS displayName,u.identity_code AS identityCode FROM group_report r JOIN app_user u ON u.id=r.reporter_id WHERE r.workspace_id=? ORDER BY r.created_at DESC LIMIT 100",id);}
 @Transactional public void resolve(long id,String report,String status){manager(lock(id),current.requireCurrent());if(!Set.of("RESOLVED","DISMISSED").contains(status))throw bad("处理状态无效");if(db.update("UPDATE group_report SET status=? WHERE id=? AND workspace_id=? AND status='OPEN'",status,report,id)==0)throw bad("举报已经处理或不存在");notifyGroup(id);}
}
